css:
.section_arc-hero{position:relative}
.ab_dbh{position:relative;padding-top:clamp(120px,14vw,170px);padding-bottom:clamp(30px,4vw,50px)}
.ab_planet.is-dbh{right:clamp(10px,6vw,110px);top:clamp(150px,16vw,210px);width:clamp(120px,19vw,290px);z-index:2}
.ab_dbh_top{position:relative;z-index:4;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;grid-row-gap:14px;grid-column-gap:24px}
.ab_crumb{color:var(--_color---text--tertiary)}
.ab_crumb_link{color:var(--_color---text--tertiary);text-decoration:none}
.ab_crumb_link:hover{color:var(--_color---text--primary)}
.ab_crumb_current{color:var(--_color---text--primary);font-weight:500}
.ab_dbh_eyebrow{position:relative;z-index:4;display:flex;align-items:center;grid-row-gap:12px;grid-column-gap:12px;margin-top:clamp(40px,6vw,80px);color:var(--_color---brand--signal);text-transform:uppercase;letter-spacing:0.14em}
.ab_dbh_title{position:relative;z-index:4;margin-top:18px;font-weight:900;font-size:clamp(52px,10.5vw,180px);line-height:0.86;letter-spacing:-0.03em;text-transform:uppercase}
.ab_dbh_word{display:block;width:max-content;max-width:100%}
.ab_dbh_sum{position:relative;z-index:4;max-width:52ch;margin-top:26px;font-size:clamp(18px,1.7vw,22px);color:var(--_color---text--secondary)}
.ab_meta{position:relative;z-index:4;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));margin-top:clamp(36px,5vw,64px);border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair);background-color:rgba(7,8,13,0.5)}
.ab_meta_item{display:flex;flex-direction:column;grid-row-gap:6px;grid-column-gap:6px;min-width:0;padding-top:16px;padding-right:18px;padding-bottom:18px;padding-left:18px;border-right-width:1px;border-right-style:solid;border-right-color:var(--_color---neutral--hair)}
.ab_meta_label{font-size:11px;letter-spacing:0.12em;text-transform:uppercase;color:var(--_color---text--tertiary)}
.ab_meta_value{font-size:15px;color:var(--_color---text--primary);overflow-wrap:anywhere}
.ab_meta_live{display:inline-flex;align-items:center;grid-row-gap:8px;grid-column-gap:8px;color:#3BE38A}
@media screen and (max-width: 991px) {
.ab_meta{grid-template-columns:repeat(3,minmax(0,1fr))}
}
@media screen and (max-width: 767px) {
.ab_planet.is-dbh{top:96px;right:14px;width:120px;opacity:0.9}
}
@media screen and (max-width: 479px) {
.ab_meta{grid-template-columns:repeat(2,minmax(0,1fr))}
}
